def list_bases(status=None, owner_user_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, credential_id=None, extra=None):
        # Best-effort request logging if a collection exists; never fail the call because logging failed.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
                "extra": extra or {},
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        # Opaque cursor: base64url("v1:<offset>")
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(cur + pad).decode("utf-8")
            if not raw.startswith("v1:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"v1:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("list_bases", "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status; must be one of: active, archived, deleted.")
    if owner_user_id is not None and not isinstance(owner_user_id, str):
        _log("list_bases", "VALIDATION_ERROR", "Invalid owner_user_id")
        return _err("VALIDATION_ERROR", "owner_user_id must be a string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("list_bases", "VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
        _log("list_bases", "VALIDATION_ERROR", "Invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name.")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("list_bases", "VALIDATION_ERROR", "Invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
    offset = _parse_cursor(cursor)
    if offset is None:
        _log("list_bases", "VALIDATION_ERROR", "Malformed cursor")
        return _err("VALIDATION_ERROR", "Malformed cursor.")

    bases = _load("bases.json")
    if not isinstance(bases, list):
        bases = []

    # Business rule: list_bases returns bases where status != 'deleted' (unless explicitly filtered? schema says always)
    # Implement as: default excludes deleted; if status provided, respect it.
    res = []
    for b in bases:
        if not isinstance(b, dict):
            continue
        b_status = b.get("status")
        if status is None:
            if b_status == "deleted":
                continue
        else:
            if b_status != status:
                continue
        if owner_user_id is not None and b.get("owner_user_id") != owner_user_id:
            continue
        res.append(b)

    reverse = (order == "desc")

    def _sort_key(row):
        v = row.get(sort)
        # handle missing and types: ensure deterministic ordering
        if v is None:
            return ""
        return v

    # stable sort then tie-break on id
    res.sort(key=lambda r: (_sort_key(r), r.get("id", "")), reverse=reverse)

    total = len(res)
    page = res[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    out = {
        "bases": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "sort": {"field": sort, "order": order}
    }
    _log("list_bases", "OK")
    return out

