    base = next((b for b in bases if isinstance(b, dict) and b.get("id") == base_id), None)
    if base is None:
        _log("list_tables", "NOT_FOUND", "Base not found")
        return _err("NOT_FOUND", "Base not found.", base_id=base_id)

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []

    # Business rule: list_tables returns tables for base where status != 'deleted' unless explicit filter
    res = []
