        },
        "sort": {"field": sort, "order": order},
        "base": {"id": base_id, "name": base.get("name"), "status": base.get("status")}
    }
    _log("list_tables", "OK")
    return out

def create_table(base_id, name, primary_field, description=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, credential_id=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "message": message,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
                "extra": extra or {},
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _gen_id(prefix, existing_ids):
        # 20 chars base32-ish uppercase (not strict, but matches ^prefix_[0-9A-Z]{18,}$)
        import random, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(1000):
            s = "".join(random.choice(alphabet) for _ in range(20))
            _id = f"{prefix}_{s}"
            if _id not in existing_ids:
                return _id
        return None

    def _is_json_object(x):
        return isinstance(x, dict)

    def _validate_choices(choices):
        if not isinstance(choices, list) or len(choices) == 0:
            return False, "options.choices must be a non-empty array."
        names = []
        for c in choices:
            if not isinstance(c, dict):
                return False, "Each choice must be an object."
            n = c.get("name")
            if not isinstance(n, str) or not n.strip():
                return False, "Each choice.name must be a non-empty string."
            names.append(n)
        if len(set(names)) != len(names):
            return False, "Choice names must be unique."
        return True, None

    def _validate_field_definition(fd, tables_rows):
        if not isinstance(fd, dict):
            return "primary_field must be an object."
        if "name" not in fd or "type" not in fd:
            return "primary_field.name and primary_field.type are required."
        if not isinstance(fd.get("name"), str) or len(fd.get("name")) < 1 or len(fd.get("name")) > 255:
            return "primary_field.name must be a non-empty string (1..255)."
        ftype = fd.get("type")
        allowed = ["singleLineText", "multilineText", "number", "checkbox", "singleSelect", "multipleSelects", "date",
                   "dateTime", "email", "url", "phoneNumber", "attachment", "linkToAnotherRecord", "lookup", "formula",
                   "createdTime", "lastModifiedTime"]
        if not isinstance(ftype, str) or ftype not in allowed:
            return "primary_field.type is unsupported."
        options = fd.get("options", {})
        if options is None:
            options = {}
        if not _is_json_object(options):
            return "primary_field.options must be a JSON object."
        # type-specific checks
        if ftype in ("singleSelect", "multipleSelects"):
            ok, msg = _validate_choices(options.get("choices"))
            if not ok:
                return msg
        if ftype == "linkToAnotherRecord":
            linked = options.get("linked_table_id")
            if not isinstance(linked, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", linked):
                return "For linkToAnotherRecord, options.linked_table_id must be a valid table id."
            tgt = next((t for t in tables_rows if isinstance(t, dict) and t.get("id") == linked and t.get("status") != "deleted"), None)
            if tgt is None:
                return "For linkToAnotherRecord, options.linked_table_id must reference an existing non-deleted table."
        # is_unique constraints
        is_unique = fd.get("is_unique", False)
        if is_unique is None:
            is_unique = False
        if not isinstance(is_unique, bool):
            return "primary_field.is_unique must be boolean."
        if is_unique and ftype not in ("singleLineText", "email", "url", "phoneNumber", "number"):
            return "primary_field.is_unique is only allowed for singleLineText, email, url, phoneNumber, number."
        is_required = fd.get("is_required", False)
        if is_required is None:
            is_required = False
        if not isinstance(is_required, bool):
            return "primary_field.is_required must be boolean."
        return None

    # Validate inputs
    if not isinstance(base_id, str) or not re.match(r"^bas_[0-9A-Z]{18,}$", base_id):
        _log("create_table", "VALIDATION_ERROR", "Invalid base_id")
        return _err("VALIDATION_ERROR", "base_id is malformed.")
    if not isinstance(name, str) or len(name) < 1 or len(name) > 255:
        _log("create_table", "VALIDATION_ERROR", "Invalid table name")
        return _err("VALIDATION_ERROR", "name must be a non-empty string (1..255).")
    if description is not None and not isinstance(description, str):
        _log("create_table", "VALIDATION_ERROR", "Invalid description")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if not isinstance(primary_field, dict):
        _log("create_table", "VALIDATION_ERROR", "Invalid primary_field")
        return _err("VALIDATION_ERROR", "primary_field must be an object.")

    bases = _load("bases.json")
    if not isinstance(bases, list):
        bases = []
    base = next((b for b in bases if isinstance(b, dict) and b.get("id") == base_id), None)
    if base is None:
        _log("create_table", "NOT_FOUND", "Base not found")
        return _err("NOT_FOUND", "Base not found.", base_id=base_id)
    if base.get("status") == "deleted":
        _log("create_table", "INVALID_TRANSITION", "Cannot create table in deleted base")
        return _err("INVALID_TRANSITION", "Cannot create a table in a deleted base.", base_id=base_id)

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []
    fields = _load("fields.json")
    if not isinstance(fields, list):
        fields = []

    # Validate primary field definition (needs tables for link target check)
    msg = _validate_field_definition(primary_field, tables)
    if msg:
        _log("create_table", "VALIDATION_ERROR", msg)
        return _err("VALIDATION_ERROR", msg)

    # Enforce unique(base_id, name) where status != 'deleted'
    for t in tables:
        if not isinstance(t, dict):
            continue
        if t.get("base_id") == base_id and t.get("name") == name and t.get("status") != "deleted":
            _log("create_table", "CONFLICT", "Table name already exists")
            return _err("CONFLICT", "A non-deleted table with this name already exists in the base.", base_id=base_id, name=name)

    existing_table_ids = {t.get("id") for t in tables if isinstance(t, dict)}
    existing_field_ids = {f.get("id") for f in fields if isinstance(f, dict)}

    tbl_id = _gen_id("tbl", existing_table_ids)
    fld_id = _gen_id("fld", existing_field_ids)
    if tbl_id is None or fld_id is None:
        _log("create_table", "CONFLICT", "ID generation failed")
        return _err("CONFLICT", "Could not allocate a new id; please retry.")

    now = _now()

    # Create table + primary field
    table_row = {
        "id": tbl_id,
        "base_id": base_id,
        "name": name,
        "description": description,
        "primary_field_id": fld_id,
        "schema_version": 1,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # position: next available in table (1 since new table)
    field_row = {
        "id": fld_id,
        "table_id": tbl_id,
        "name": primary_field.get("name"),
        "type": primary_field.get("type"),
        "options": primary_field.get("options", {}) if primary_field.get("options", {}) is not None else {},
        "is_required": bool(primary_field.get("is_required", False)),
        "is_unique": bool(primary_field.get("is_unique", False)),
        "is_indexed": True if primary_field.get("type") in ("singleLineText", "multilineText", "email", "url", "phoneNumber") else False,
        "position": 1,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Persist
    tables.append(table_row)
    fields.append(field_row)
    _save("tables.json", tables)
    _save("fields.json", fields)

    out = {"table": table_row, "primary_field": field_row}
    _log("create_table", "OK", extra={"table_id": tbl_id, "base_id": base_id})
    return out

def update_table(table_id, name=None, description=None, primary_field_id=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_table"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_s, code=None, message=None, meta=None):
        fn = _get_log_store()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        rows.append(row)
        _save(fn, rows)

    # Validate inputs first (but accept plausible IDs even if they don't match strict regex, to avoid false negatives)
    if not isinstance(table_id, str) or not table_id.startswith("tbl_"):
        out = _err("VALIDATION_ERROR", "Malformed table_id.", field="table_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 255)):
        out = _err("VALIDATION_ERROR", "name must be a non-empty string (1..255).", field="name")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if description is not None and not isinstance(description, str):
        out = _err("VALIDATION_ERROR", "description must be a string.", field="description")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if primary_field_id is not None and (not isinstance(primary_field_id, str) or not primary_field_id.startswith("fld_")):
        out = _err("VALIDATION_ERROR", "primary_field_id is malformed.", field="primary_field_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if status is not None and (not isinstance(status, str) or status not in ("active", "archived", "deleted")):
        out = _err("VALIDATION_ERROR", "Unsupported status.", field="status", allowed=["active", "archived", "deleted"])
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []
    tbl_idx = next((i for i, t in enumerate(tables) if t.get("id") == table_id), None)
    if tbl_idx is None:
        out = _err("NOT_FOUND", "Table not found.", table_id=table_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    table = tables[tbl_idx]
    if table.get("status") == "deleted":
        out = _err("NOT_FOUND", "Table not found.", table_id=table_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    # Enforce rename uniqueness within base among non-deleted tables
    if name is not None:
        base_id = table.get("base_id")
        for t in tables:
            if t.get("id") != table_id and t.get("base_id") == base_id and t.get("status") != "deleted" and t.get("name") == name:
                out = _err("CONFLICT", "A non-deleted table with this name already exists in the base.", base_id=base_id, name=name)
                _log("error", out["error"]["code"], out["error"]["message"])
                return out

    # Validate primary_field_id belongs to same table and is active
    if primary_field_id is not None:
        fields_rows = _load("fields.json")
        if not isinstance(fields_rows, list):
            fields_rows = []
        pf = next((f for f in fields_rows if f.get("id") == primary_field_id), None)
        if not pf or pf.get("status") != "active" or pf.get("table_id") != table_id:
            out = _err(
                "VALIDATION_ERROR",
                "primary_field_id must reference an active field in the same table.",
                field="primary_field_id",
                table_id=table_id,
                primary_field_id=primary_field_id,
            )
            _log("error", out["error"]["code"], out["error"]["message"])
            return out

    # Enforce lifecycle transitions
    if status is not None:
        cur = table.get("status")
        allowed = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        if cur not in allowed:
            out = _err("INVALID_TRANSITION", "Table is in an unknown lifecycle state.", current=cur)
            _log("error", out["error"]["code"], out["error"]["message"])
            return out
        if status != cur and status not in allowed[cur]:
            out = _err("INVALID_TRANSITION", "Illegal table status transition.", current=cur, target=status, allowed=allowed[cur])
            _log("error", out["error"]["code"], out["error"]["message"])
            return out

        # If deleting, cascade soft-delete fields and records and mark index rows deleted
        if status == "deleted" and cur != "deleted":
            # Restrict/cascade behavior: this server uses soft deletion cascade for table delete.
            fields_rows = _load("fields.json")
            if not isinstance(fields_rows, list):
                fields_rows = []
            records_rows = _load("records.json")
            if not isinstance(records_rows, list):
                records_rows = []
            idx_rows = _load("record_search_index.json")
            if not isinstance(idx_rows, list):
                idx_rows = []

            now = _now()
            for f in fields_rows:
                if f.get("table_id") == table_id and f.get("status") != "deleted":
                    f["status"] = "deleted"
                    f["updated_at"] = now
            for r in records_rows:
                if r.get("table_id") == table_id and r.get("status") != "deleted":
                    r["status"] = "deleted"
                    r["deleted_at"] = now
                    r["updated_at"] = now
            for ix in idx_rows:
                if ix.get("table_id") == table_id and ix.get("status") != "deleted":
                    ix["status"] = "deleted"
                    ix["updated_at"] = now

            _save("fields.json", fields_rows)
            _save("records.json", records_rows)
            _save("record_search_index.json", idx_rows)

    # Apply updates
    changed = False
    now = _now()
    if name is not None and name != table.get("name"):
        table["name"] = name
        changed = True
    if description is not None and description != table.get("description"):
        table["description"] = description
        changed = True
    if primary_field_id is not None and primary_field_id != table.get("primary_field_id"):
        table["primary_field_id"] = primary_field_id
        changed = True
    if status is not None and status != table.get("status"):
        table["status"] = status
        changed = True

    if not changed:
        # No success without effect: return the existing row as "updated" only if real API is idempotent.
        # For table PATCH, idempotent is acceptable: return current state.
        out = {"table": table, "id": table.get("id")}
        _log("ok")
        return out

    table["updated_at"] = now
    # schema_version increments on table/field changes? For table metadata, keep schema_version same unless primary_field changes.
    # In Airtable-like semantics, primary field assignment affects schema; increment for primary_field_id change.
    if primary_field_id is not None:
        try:
            sv = int(table.get("schema_version") or 1)
        except Exception:
            sv = 1
        table["schema_version"] = max(1, sv + 1)
        # mark existing index rows stale (schema change)
        idx_rows = _load("record_search_index.json")
        if not isinstance(idx_rows, list):
            idx_rows = []
        for ix in idx_rows:
            if ix.get("table_id") == table_id and ix.get("status") == "fresh":
                ix["status"] = "stale"
                ix["updated_at"] = now
        _save("record_search_index.json", idx_rows)

    tables[tbl_idx] = table
    _save("tables.json", tables)
    out = {"table": table}
    _log("ok")
    return out

def create_field(table_id, name, type, options=None, is_required=None, is_unique=None, is_indexed=None, position=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        # Prefer common filenames if present; otherwise no-ops but still try to persist if file exists.
        candidates = [
            "request_logs.json",
            "requests.json",
            "usage.json",
            "audit_logs.json",
            "api_logs.json",
        ]
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                return fn
        return None

    def _log(endpoint, status, latency_ms, meta=None):
        fn = _get_log_store()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta and isinstance(meta, dict):
            row.update({"meta": meta})
        rows.append(row)
        _save(fn, rows)

    start = time.time()
    endpoint = "create_field"

    try:
        if not isinstance(table_id, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", table_id):
            out = _err("VALIDATION_ERROR", "Malformed table_id.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out
        if not isinstance(name, str) or not (1 <= len(name) <= 255):
            out = _err("VALIDATION_ERROR", "Invalid name; must be length 1..255.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out
        allowed_types = [
            "singleLineText", "multilineText", "number", "checkbox", "singleSelect", "multipleSelects",
            "date", "dateTime", "email", "url", "phoneNumber", "attachment", "linkToAnotherRecord",
            "lookup", "formula", "createdTime", "lastModifiedTime"
        ]
        if not isinstance(type, str) or type not in allowed_types:
            out = _err("VALIDATION_ERROR", "Invalid field type.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out
        if options is None:
            options = {}
        if not isinstance(options, dict):
            out = _err("VALIDATION_ERROR", "options must be a JSON object.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out
        if is_required is None:
            is_required = False
        if is_unique is None:
            is_unique = False
        if is_indexed is None:
            is_indexed = False
        if not isinstance(is_required, bool) or not isinstance(is_unique, bool) or not isinstance(is_indexed, bool):
            out = _err("VALIDATION_ERROR", "is_required, is_unique, and is_indexed must be booleans.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out
        if position is None:
            position = 0
        if not isinstance(position, int) or position < 0:
            out = _err("VALIDATION_ERROR", "position must be an integer >= 0.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        # Type/options validation rules
        if is_unique and type not in ("singleLineText", "email", "url", "phoneNumber", "number"):
            out = _err("VALIDATION_ERROR", "is_unique=true is only allowed for singleLineText, email, url, phoneNumber, number.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        if type in ("singleSelect", "multipleSelects"):
            choices = options.get("choices")
            if not isinstance(choices, list) or len(choices) == 0:
                out = _err("VALIDATION_ERROR", "options.choices must be a non-empty array for select fields.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out
            names = []
            for c in choices:
                if not isinstance(c, dict) or not isinstance(c.get("name"), str) or len(c["name"]) == 0:
                    out = _err("VALIDATION_ERROR", "Each select choice must be an object with a non-empty 'name'.")
                    _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                    return out
                names.append(c["name"])
            if len(set(names)) != len(names):
                out = _err("VALIDATION_ERROR", "Select choice names must be unique.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out

        tables = _load("tables.json")
        if not isinstance(tables, list):
            tables = []
        table = next((t for t in tables if t.get("id") == table_id), None)
        if not table or table.get("status") == "deleted":
            out = _err("NOT_FOUND", "Table not found.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        fields = _load("fields.json")
        if not isinstance(fields, list):
            fields = []

        # Enforce unique(table_id, name) where status != 'deleted'
        for f in fields:
            if f.get("table_id") == table_id and f.get("status") != "deleted" and f.get("name") == name:
                out = _err("CONFLICT", "A non-deleted field with this name already exists in the table.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out

        if type == "linkToAnotherRecord":
            linked = options.get("linked_table_id")
            if not isinstance(linked, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", linked):
                out = _err("VALIDATION_ERROR", "options.linked_table_id must be a valid table id for linkToAnotherRecord.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out
            linked_table = next((t for t in tables if t.get("id") == linked and t.get("status") != "deleted"), None)
            if not linked_table:
                out = _err("VALIDATION_ERROR", "options.linked_table_id references a table that does not exist.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out

        if type in ("lookup", "formula"):
            # Minimal config checks without implementing full expressions
            if type == "formula":
                expr = options.get("expression")
                if expr is None or not isinstance(expr, str) or not expr.strip():
                    out = _err("VALIDATION_ERROR", "options.expression must be a non-empty string for formula fields.")
                    _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                    return out
            if type == "lookup":
                # typical: linked_field_id + target_field_id
                lfid = options.get("linked_field_id")
                tfid = options.get("target_field_id")
                if not isinstance(lfid, str) or not isinstance(tfid, str):
                    out = _err("VALIDATION_ERROR", "options.linked_field_id and options.target_field_id must be provided for lookup fields.")
                    _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                    return out

        # Determine new field position: schema uses 1-based "position"
        active_non_deleted = [f for f in fields if f.get("table_id") == table_id and f.get("status") != "deleted"]
        max_pos = 0
        for f in active_non_deleted:
            p = f.get("position")
            if isinstance(p, int) and p > max_pos:
                max_pos = p
        insert_at = min(position, len(active_non_deleted))  # 0-based insertion index
        # Shift positions (1-based) for non-deleted fields at/after insertion point
        # Sort by existing position to apply stable shift
        active_sorted = sorted(active_non_deleted, key=lambda x: (x.get("position") if isinstance(x.get("position"), int) else 10**9, x.get("created_at", "")))
        for idx, f in enumerate(active_sorted):
            desired = idx + 1
            # normalize first
            if not isinstance(f.get("position"), int) or f["position"] < 1:
                f["position"] = desired
        active_sorted = sorted(active_non_deleted, key=lambda x: x.get("position", 10**9))
        for f in active_sorted:
            if f.get("position", 10**9) >= (insert_at + 1):
                f["position"] = int(f.get("position", insert_at + 1)) + 1

        def _new_id(prefix):
            return prefix + "_" + secrets.token_hex(10).upper()

        now = _now()
        new_field = {
            "id": _new_id("fld"),
            "table_id": table_id,
            "name": name,
            "type": type,
            "options": options,
            "is_required": bool(is_required),
            "is_unique": bool(is_unique),
            "is_indexed": bool(is_indexed),
            "position": insert_at + 1,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        # Persist shifted positions back into fields list
        # (active_non_deleted references objects from fields list, so mutations already applied)
        fields.append(new_field)

        # Increment tables.schema_version and possibly set primary_field_id
        if not isinstance(table.get("schema_version"), int) or table["schema_version"] < 1:
            table["schema_version"] = 1
        table["schema_version"] += 1
        table["updated_at"] = now

        # If no primary_field_id, set to first writable text-like field created
        if not table.get("primary_field_id"):
            if type in ("singleLineText", "multilineText"):
                table["primary_field_id"] = new_field["id"]

        # Validate primary_field_id constraint (if set) references active field in same table
        if table.get("primary_field_id"):
            pf = next((f for f in fields if f.get("id") == table["primary_field_id"]), None)
            if not pf or pf.get("table_id") != table_id or pf.get("status") != "active":
                out = _err("VALIDATION_ERROR", "primary_field_id must reference an active field in the same table.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out

        # Mark search index rows stale due to schema change
        rsi = _load("record_search_index.json")
        if not isinstance(rsi, list):
            rsi = []
        for row in rsi:
            if row.get("table_id") == table_id and row.get("status") in ("fresh", "stale"):
                row["status"] = "stale"
                row["updated_at"] = now

        _save("fields.json", fields)
        _save("tables.json", tables)
        _save("record_search_index.json", rsi)

        out = {"field": new_field}
        _log(endpoint, "ok", (time.time() - start) * 1000)
        return out
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
        return out

def update_field(field_id, name=None, options=None, is_required=None, is_unique=None, is_indexed=None, position=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_field"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_s, code=None, message=None, meta=None):
        log_fn = _pick_logfile()
        if not log_fn:
            return
        rows = _load(log_fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + str(int(time.time() * 1000)),
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        rows.append(row)
        _save(log_fn, rows)

    def _valid_transition(old, new):
        transitions = {
            "active": {"hidden", "deleted"},
            "hidden": {"active", "deleted"},
            "deleted": set(),
        }
        return new in transitions.get(old, set())

    def _mark_table_index_stale(table_id, table_schema_version):
        idx = _load("record_search_index.json")
        if not isinstance(idx, list):
            return
        changed = False
        now = _now()
        for row in idx:
            if row.get("table_id") != table_id:
                continue
            if row.get("status") == "deleted":
                continue
            if row.get("schema_version") != table_schema_version or row.get("status") == "fresh":
                # schema change makes index potentially stale
                if row.get("status") != "stale":
                    row["status"] = "stale"
                    row["updated_at"] = now
                    changed = True
                else:
                    # still bump updated_at to reflect schema change
                    row["updated_at"] = now
                    changed = True
        if changed:
            _save("record_search_index.json", idx)

    # Validate inputs
    if not isinstance(field_id, str) or not re.match(r"^fld_[0-9A-Z]{18,}$", field_id):
        _log("error", "VALIDATION_ERROR", "Malformed field_id.", {"field": "field_id"})
        return _err("VALIDATION_ERROR", "Malformed field_id.", field="field_id")

    if name is not None and (not isinstance(name, str) or len(name) < 1):
        _log("error", "VALIDATION_ERROR", "Empty name.", {"field": "name"})
        return _err("VALIDATION_ERROR", "Empty name.", field="name")

    if options is not None and not isinstance(options, dict):
        _log("error", "VALIDATION_ERROR", "options must be an object.", {"field": "options"})
        return _err("VALIDATION_ERROR", "options must be an object.", field="options")

    for bname, bval in (("is_required", is_required), ("is_unique", is_unique), ("is_indexed", is_indexed)):
        if bval is not None and not isinstance(bval, bool):
            _log("error", "VALIDATION_ERROR", f"{bname} must be boolean.", {"field": bname})
            return _err("VALIDATION_ERROR", f"{bname} must be boolean.", field=bname)

    if position is not None:
        if not isinstance(position, int) or position < 0:
            _log("error", "VALIDATION_ERROR", "Invalid position.", {"field": "position"})
            return _err("VALIDATION_ERROR", "Invalid position.", field="position")

    if status is not None and status not in ("active", "hidden", "deleted"):
        _log("error", "VALIDATION_ERROR", "Unsupported status.", {"field": "status"})
        return _err("VALIDATION_ERROR", "Unsupported status.", field="status")

    fields_rows = _load("fields.json")
    if not isinstance(fields_rows, list):
        fields_rows = []
    field_row = None
    for r in fields_rows:
        if r.get("id") == field_id:
            field_row = r
            break
    if not field_row:
        _log("error", "NOT_FOUND", "Field not found.", {"field_id": field_id})
        return _err("NOT_FOUND", "Field not found.", field_id=field_id)

    # Resolve table
    tables_rows = _load("tables.json")
    if not isinstance(tables_rows, list):
        tables_rows = []
    table_row = None
    table_id = field_row.get("table_id")
    for t in tables_rows:
        if t.get("id") == table_id:
            table_row = t
            break
    if not table_row:
        _log("error", "NOT_FOUND", "Owning table not found.", {"table_id": table_id})
        return _err("NOT_FOUND", "Owning table not found.", table_id=table_id)

    if table_row.get("status") == "deleted":
        _log("error", "CONFLICT", "Cannot modify fields in a deleted table.", {"table_id": table_id})
        return _err("CONFLICT", "Cannot modify fields in a deleted table.", table_id=table_id)

    # Uniqueness: unique(table_id, name) where status != 'deleted'
    if name is not None:
        for r in fields_rows:
            if r.get("id") == field_id:
                continue
            if r.get("table_id") == table_id and r.get("status") != "deleted" and r.get("name") == name:
                _log("error", "CONFLICT", "Field name already exists in table.", {"name": name, "table_id": table_id})
                return _err("CONFLICT", "Field name already exists in table.", name=name, table_id=table_id)

    # Status transition validation
    if status is not None:
        old_status = field_row.get("status")
        if status != old_status and not _valid_transition(old_status, status):
            _log("error", "INVALID_TRANSITION", "Illegal lifecycle transition.", {"from": old_status, "to": status})
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition.", from_status=old_status, to_status=status)

    # Constraint: if is_unique=true then type must be one of scalar set
    new_is_unique = field_row.get("is_unique") if is_unique is None else is_unique
    if new_is_unique:
        if field_row.get("type") not in ("singleLineText", "email", "url", "phoneNumber", "number"):
            _log("error", "VALIDATION_ERROR", "is_unique not supported for this field type.", {"field": "is_unique"})
            return _err("VALIDATION_ERROR", "is_unique not supported for this field type.", field="is_unique")

    # Options compatibility checks for select/link types
    ftype = field_row.get("type")
    new_options = field_row.get("options") if options is None else options
    if not isinstance(new_options, dict):
        _log("error", "VALIDATION_ERROR", "options must be an object.", {"field": "options"})
        return _err("VALIDATION_ERROR", "options must be an object.", field="options")

    if ftype in ("singleSelect", "multipleSelects"):
        choices = new_options.get("choices")
        if not isinstance(choices, list) or len(choices) < 1:
            _log("error", "VALIDATION_ERROR", "options.choices must be a non-empty array.", {"field": "options"})
            return _err("VALIDATION_ERROR", "options.choices must be a non-empty array.", field="options")
        names = []
        for c in choices:
            if not isinstance(c, dict) or not isinstance(c.get("name"), str) or not c.get("name"):
                _log("error", "VALIDATION_ERROR", "Each choice must be an object with non-empty name.", {"field": "options"})
                return _err("VALIDATION_ERROR", "Each choice must be an object with non-empty name.", field="options")
            names.append(c["name"])
        if len(set(names)) != len(names):
            _log("error", "VALIDATION_ERROR", "Choice names must be unique.", {"field": "options"})
            return _err("VALIDATION_ERROR", "Choice names must be unique.", field="options")

    if ftype == "linkToAnotherRecord":
        linked_table_id = new_options.get("linked_table_id")
        if not isinstance(linked_table_id, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", linked_table_id):
            _log("error", "VALIDATION_ERROR", "options.linked_table_id must reference a table id.", {"field": "options"})
            return _err("VALIDATION_ERROR", "options.linked_table_id must reference a table id.", field="options")
        ok = any(t.get("id") == linked_table_id and t.get("status") != "deleted" for t in tables_rows)
        if not ok:
            _log("error", "NOT_FOUND", "linked_table_id not found.", {"linked_table_id": linked_table_id})
            return _err("NOT_FOUND", "linked_table_id not found.", linked_table_id=linked_table_id)

    # Apply updates
    changed = False
    if name is not None and name != field_row.get("name"):
        field_row["name"] = name
        changed = True
    if options is not None and options != field_row.get("options"):
        field_row["options"] = options
        changed = True
    if is_required is not None and is_required != field_row.get("is_required"):
        field_row["is_required"] = is_required
        changed = True
    if is_unique is not None and is_unique != field_row.get("is_unique"):
        field_row["is_unique"] = is_unique
        changed = True
    if is_indexed is not None and is_indexed != field_row.get("is_indexed"):
        field_row["is_indexed"] = is_indexed
        changed = True
    if position is not None and position != field_row.get("position"):
        # tool defines zero-based, store uses position>=1; convert
        field_row["position"] = int(position) + 1
        changed = True
    if status is not None and status != field_row.get("status"):
        field_row["status"] = status
        changed = True

    if not changed:
        # idempotent no-op should still be observable but should return the current resource
        _log("ok")
        return {"field": field_row}

    now = _now()
    field_row["updated_at"] = now

    # Increment tables.schema_version by 1 (schema change)
    try:
        sv = int(table_row.get("schema_version") or 0)
    except Exception:
        sv = 0
    if sv < 1:
        sv = 1
    table_row["schema_version"] = sv + 1
    table_row["updated_at"] = now

    _save("fields.json", fields_rows)
    _save("tables.json", tables_rows)

    # Mark index rows stale for table due to schema change affecting indexed fields
    _mark_table_index_stale(table_id, table_row["schema_version"])

    _log("ok")
    return {"field": field_row}

def list_records(table_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        candidates = ["request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"]
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(endpoint, status_s, latency_ms, meta=None):
        fn = _get_log_store()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta and isinstance(meta, dict):
            row.update({"meta": meta})
        rows.append(row)
        _save(fn, rows)

    start = time.time()
    endpoint = "list_records"

    try:
        if not isinstance(table_id, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", table_id):
            out = _err("VALIDATION_ERROR", "Malformed table_id.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        if status is None:
            status = "active"
        if status not in ("active", "deleted"):
            out = _err("VALIDATION_ERROR", "Invalid status filter.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        if limit is None:
            limit = 100
        if not isinstance(limit, int) or not (1 <= limit <= 100):
            out = _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        sort_key = "created_at"
        sort_dir = 1
        if sort is not None:
            if not isinstance(sort, str) or not sort.strip():
                out = _err("VALIDATION_ERROR", "Invalid sort specification.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out
            s = sort.strip()
            if s.startswith("-"):
                sort_dir = -1
                s = s[1:]
            if s not in ("created_at", "updated_at", "id"):
                out = _err("VALIDATION_ERROR", "Invalid sort field; allowed: created_at, updated_at, id.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out
            sort_key = s

        tables = _load("tables.json")
        if not isinstance(tables, list):
            tables = []
        table = next((t for t in tables if t.get("id") == table_id), None)
        if not table or table.get("status") == "deleted":
            out = _err("NOT_FOUND", "Table not found.")
            _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
            return out

        records = _load("records.json")
        if not isinstance(records, list):
            records = []

        filtered = [r for r in records if r.get("table_id") == table_id and r.get("status") == status]

        def _val(r):
            v = r.get(sort_key)
            if v is None:
                return ""
            return v

        filtered.sort(key=lambda r: (_val(r), r.get("id", "")), reverse=(sort_dir == -1))

        # Cursor is opaque; encode start offset + sort spec. If invalid -> VALIDATION_ERROR
        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                out = _err("VALIDATION_ERROR", "Malformed cursor.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                payload = json.loads(raw.decode("utf-8"))
                if not isinstance(payload, dict):
                    raise ValueError("bad payload")
                if payload.get("table_id") != table_id or payload.get("status") != status:
                    raise ValueError("cursor context mismatch")
                if payload.get("sort_key") != sort_key or payload.get("sort_dir") != sort_dir:
                    raise ValueError("cursor sort mismatch")
                offset = payload.get("offset")
                if not isinstance(offset, int) or offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                out = _err("VALIDATION_ERROR", "Malformed cursor.")
                _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
                return out

        page = filtered[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < len(filtered)
        next_cursor = None
        if has_more:
            payload = {"table_id": table_id, "status": status, "sort_key": sort_key, "sort_dir": sort_dir, "offset": next_offset}
            next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

        out = {
            "records": page,
            "meta": {"total": len(filtered), "has_more": has_more, "next_cursor": next_cursor},
        }
        _log(endpoint, "ok", (time.time() - start) * 1000)
        return out
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log(endpoint, "error", (time.time() - start) * 1000, {"code": out["error"]["code"]})
        return out

def create_record(table_id, fields, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_record"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_s, code=None, message=None, meta=None):
        log_fn = _pick_logfile()
        if not log_fn:
            return
        rows = _load(log_fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + str(int(time.time() * 1000)),
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        rows.append(row)
        _save(log_fn, rows)

    def _new_id(prefix, n=19):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(n))

    def _is_read_only(ftype):
        return ftype in ("lookup", "formula", "createdTime", "lastModifiedTime")

    def _normalize_text(v):
        return " ".join(str(v).lower().split())

    def _validate_value(field_row, value):
        ftype = field_row.get("type")
        opts = field_row.get("options") if isinstance(field_row.get("options"), dict) else {}
        if value is None:
            return True, None

        if ftype in ("singleLineText", "multilineText", "email", "url", "phoneNumber"):
            return (isinstance(value, str), "Expected string.")
        if ftype == "number":
            return ((isinstance(value, (int, float)) and not isinstance(value, bool)), "Expected number.")
        if ftype == "checkbox":
            return (isinstance(value, bool), "Expected boolean.")
        if ftype in ("date", "dateTime"):
            # accept ISO strings
            return (isinstance(value, str) and len(value) >= 4, "Expected ISO date/time string.")
        if ftype == "singleSelect":
            choices = opts.get("choices")
            if not isinstance(choices, list) or not choices:
                return False, "Field choices misconfigured."
            # accept either choice name or {name:...}
            if isinstance(value, str):
                ok = any(isinstance(c, dict) and c.get("name") == value for c in choices)
                return ok, "Invalid choice."
            if isinstance(value, dict) and isinstance(value.get("name"), str):
                ok = any(isinstance(c, dict) and c.get("name") == value.get("name") for c in choices)
                return ok, "Invalid choice."
            return False, "Expected choice name."
        if ftype == "multipleSelects":
            choices = opts.get("choices")
            if not isinstance(choices, list) or not choices:
                return False, "Field choices misconfigured."
            if not isinstance(value, list):
                return False, "Expected array of choices."
            names = []
            for v in value:
                if isinstance(v, str):
                    names.append(v)
                elif isinstance(v, dict) and isinstance(v.get("name"), str):
                    names.append(v["name"])
                else:
                    return False, "Expected choice names."
            for n in names:
                if not any(isinstance(c, dict) and c.get("name") == n for c in choices):
                    return False, "Invalid choice."
            return True, None
        if ftype == "attachment":
            return (isinstance(value, list), "Expected array of attachments.")
        if ftype == "linkToAnotherRecord":
            if isinstance(value, list) and all(isinstance(v, str) for v in value):
                return True, None
            return False, "Expected array of record ids."
        # read-only types should not be writable at record level
        if _is_read_only(ftype):
            return False, "Field is read-only."
        # fallback: allow JSON-ish types
        return True, None

    # Validate inputs
    if not isinstance(table_id, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", table_id):
        _log("error", "VALIDATION_ERROR", "Malformed table_id.", {"field": "table_id"})
        return _err("VALIDATION_ERROR", "Malformed table_id.", field="table_id")
    if not isinstance(fields, dict):
        _log("error", "VALIDATION_ERROR", "fields must be an object.", {"field": "fields"})
        return _err("VALIDATION_ERROR", "fields must be an object.", field="fields")

    tables_rows = _load("tables.json")
    if not isinstance(tables_rows, list):
        tables_rows = []
    table_row = None
    for t in tables_rows:
        if t.get("id") == table_id:
            table_row = t
            break
    if not table_row or table_row.get("status") == "deleted":
        _log("error", "NOT_FOUND", "Table not found.", {"table_id": table_id})
        return _err("NOT_FOUND", "Table not found.", table_id=table_id)
    if table_row.get("status") != "active":
        _log("error", "CONFLICT", "Cannot create records in a non-active table.", {"table_status": table_row.get("status")})
        return _err("CONFLICT", "Cannot create records in a non-active table.", table_status=table_row.get("status"))

    fields_rows = _load("fields.json")
    if not isinstance(fields_rows, list):
        fields_rows = []
    table_fields = [f for f in fields_rows if f.get("table_id") == table_id]
    active_fields = [f for f in table_fields if f.get("status") == "active"]

    # Build field lookup by id and by name
    by_id = {f.get("id"): f for f in table_fields if isinstance(f.get("id"), str)}
    by_name = {f.get("name"): f for f in table_fields if isinstance(f.get("name"), str)}

    # Map input keys (name or id) -> field_id
    mapped = {}
    for k, v in fields.items():
        if not isinstance(k, str):
            _log("error", "VALIDATION_ERROR", "Field keys must be strings.", {"field": "fields"})
            return _err("VALIDATION_ERROR", "Field keys must be strings.", field="fields")
        frow = by_id.get(k) or by_name.get(k)
        if not frow:
            _log("error", "VALIDATION_ERROR", "Unknown field.", {"field": "fields", "unknown_field": k})
            return _err("VALIDATION_ERROR", "Unknown field.", field="fields", unknown_field=k)
        if frow.get("status") != "active":
            _log("error", "VALIDATION_ERROR", "Cannot write to non-active field.", {"field_id": frow.get("id")})
            return _err("VALIDATION_ERROR", "Cannot write to non-active field.", field_id=frow.get("id"))
        if _is_read_only(frow.get("type")):
            _log("error", "VALIDATION_ERROR", "Cannot write to read-only field type.", {"field_id": frow.get("id"), "type": frow.get("type")})
            return _err("VALIDATION_ERROR", "Cannot write to read-only field type.", field_id=frow.get("id"), field_type=frow.get("type"))
        mapped[frow["id"]] = v

    # Enforce required fields (writable types only)
    for f in active_fields:
        if not f.get("is_required"):
            continue
        if _is_read_only(f.get("type")):
            continue
        if f.get("id") not in mapped or mapped.get(f.get("id")) is None:
            _log("error", "VALIDATION_ERROR", "Missing required field value.", {"field_id": f.get("id"), "field_name": f.get("name")})
            return _err("VALIDATION_ERROR", "Missing required field value.", field_id=f.get("id"), field_name=f.get("name"))

    # Validate values
    for fid, v in mapped.items():
        frow = by_id.get(fid)
        ok, msg = _validate_value(frow, v)
        if not ok:
            _log("error", "VALIDATION_ERROR", msg or "Invalid field value.", {"field_id": fid})
            return _err("VALIDATION_ERROR", msg or "Invalid field value.", field_id=fid, field_name=frow.get("name"))

    # Uniqueness enforcement for is_unique fields across active records
    records_rows = _load("records.json")
    if not isinstance(records_rows, list):
        records_rows = []
    enforce_nulls_default = False
    for f in active_fields:
        if not f.get("is_unique"):
            continue
        fid = f.get("id")
        if fid not in mapped:
            continue
        val = mapped.get(fid)
        opts = f.get("options") if isinstance(f.get("options"), dict) else {}
        enforce_nulls = bool(opts.get("enforce_unique_nulls", enforce_nulls_default))
        if (val is None or val == "" or val == []) and not enforce_nulls:
            continue
        # compare scalar values only; for non-scalar, skip
        if isinstance(val, (dict, list)):
            _log("error", "VALIDATION_ERROR", "Unique constraint only supported for scalar values.", {"field_id": fid})
            return _err("VALIDATION_ERROR", "Unique constraint only supported for scalar values.", field_id=fid)
        for r in records_rows:
            if r.get("table_id") != table_id or r.get("status") != "active":
                continue
            other = (r.get("fields") or {}).get(fid)
            if other == val and not (other is None and not enforce_nulls):
                _log("error", "CONFLICT", "Uniqueness constraint violated.", {"field_id": fid})
                return _err("CONFLICT", "Uniqueness constraint violated.", field_id=fid, field_name=f.get("name"))

    # Create record
    now = _now()
    rec_id = _new_id("rec")
    # ensure uniqueness of generated id
    existing_ids = {r.get("id") for r in records_rows if isinstance(r, dict)}
    while rec_id in existing_ids:
        rec_id = _new_id("rec")

    stored_fields = dict(mapped)  # store by field_id
    new_row = {
        "id": rec_id,
        "table_id": table_id,
        "fields": stored_fields,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    records_rows.append(new_row)
    _save("records.json", records_rows)

    # Update/insert search index row for this record
    idx = _load("record_search_index.json")
    if not isinstance(idx, list):
        idx = []
    schema_version = int(table_row.get("schema_version") or 1)
    search_text_parts = []
    search_kv = {}
    for f in active_fields:
        fid = f.get("id")
        val = stored_fields.get(fid)
        if f.get("is_indexed"):
            # text-like into search_text
            if f.get("type") in ("singleLineText", "multilineText", "email", "url", "phoneNumber"):
                if val is not None:
                    search_text_parts.append(_normalize_text(val))
            else:
                if val is not None:
                    search_kv[fid] = val

    search_text = " ".join([p for p in search_text_parts if p]).strip()
    existing = None
    for r in idx:
        if r.get("table_id") == table_id and r.get("record_id") == rec_id:
            existing = r
            break
    if existing:
        existing["schema_version"] = schema_version
        existing["status"] = "fresh" if new_row["status"] == "active" else "deleted"
        existing["search_text"] = search_text
        existing["search_kv"] = search_kv
        existing["updated_at"] = now
    else:
        idx.append({
            "id": _new_id("rsi"),
            "table_id": table_id,
            "record_id": rec_id,
            "schema_version": schema_version,
            "status": "fresh",
            "search_text": search_text,
            "search_kv": search_kv,
            "created_at": now,
            "updated_at": now,
        })
    _save("record_search_index.json", idx)

    _log("ok")
    return {"record": new_row}

