    if not table_row or table_row.get("status") == "deleted":
        _log("error", "NOT_FOUND", "Table not found.", {"table_id": table_id})
        return _err("NOT_FOUND", "Table not found.", table_id=table_id)
    if table_row.get("status") != "active":
        _log("error", "CONFLICT", "Cannot update records in a non-active table.", {"table_status": table_row.get("status")})
        return _err("CONFLICT", "Cannot update records in a non-active table.", table_status=table_row.get("status"))

    records_rows = _load("records.json")
    if not isinstance(records_rows, list):
        records_rows = []
    rec_row = None
    for r in records_rows:
        if r.get("id") == record_id:
            rec_row = r
            break
    if not rec_row:
        _log("error", "NOT_FOUND", "Record not found.", {"record_id": record_id})
        return _err("NOT_FOUND", "Record not found.", record_id=record_id)
    if rec_row.get("table_id") != table_id:
        _log("error", "CONFLICT", "Record does not belong to the specified table.", {"record_table_id": rec_row.get("table_id")})
        return _err("CONFLICT", "Record does not belong to the specified table.", record_table_id=rec_row.get("table_id"))

    if rec_row.get("status") != "active":
        _log("error", "INVALID_TRANSITION", "Cannot update a deleted record.", {"status": rec_row.get("status")})
        return _err("INVALID_TRANSITION", "Cannot update a deleted record.", status=rec_row.get("status"))

    fields_rows = _load("fields.json")
    if not isinstance(fields_rows, list):
        fields_rows = []
    table_fields = [f for f in fields_rows if f.get("table_id") == table_id]
    active_fields = [f for f in table_fields if f.get("status") == "active"]
    by_id = {f.get("id"): f for f in table_fields if isinstance(f.get("id"), str)}
    by_name = {f.get("name"): f for f in table_fields if isinstance(f.get("name"), str)}

    # Map updates
    updates = {}
    for k, v in fields.items():
        if not isinstance(k, str):
            _log("error", "VALIDATION_ERROR", "Field keys must be strings.", {"field": "fields"})
            return _err("VALIDATION_ERROR", "Field keys must be strings.", field="fields")
        frow = by_id.get(k) or by_name.get(k)
        if not frow:
            _log("error", "VALIDATION_ERROR", "Unknown field.", {"unknown_field": k})
            return _err("VALIDATION_ERROR", "Unknown field.", unknown_field=k)
        if frow.get("status") != "active":
            _log("error", "VALIDATION_ERROR", "Cannot write to non-active field.", {"field_id": frow.get("id")})
            return _err("VALIDATION_ERROR", "Cannot write to non-active field.", field_id=frow.get("id"))
        if _is_read_only(frow.get("type")):
            _log("error", "VALIDATION_ERROR", "Cannot write to read-only field type.", {"field_id": frow.get("id"), "type": frow.get("type")})
            return _err("VALIDATION_ERROR", "Cannot write to read-only field type.", field_id=frow.get("id"), field_type=frow.get("type"))
        updates[frow["id"]] = v

    # Compute merged fields
    current = rec_row.get("fields") if isinstance(rec_row.get("fields"), dict) else {}
    merged = dict(current)
    merged.update(updates)

    # Enforce required fields (cannot clear)
    for f in active_fields:
        if not f.get("is_required"):
            continue
        if _is_read_only(f.get("type")):
            continue
        fid = f.get("id")
        if fid not in merged or merged.get(fid) is None:
            _log("error", "VALIDATION_ERROR", "Missing required field value.", {"field_id": fid, "field_name": f.get("name")})
            return _err("VALIDATION_ERROR", "Missing required field value.", field_id=fid, field_name=f.get("name"))

    # Validate updated values only (but validate required presence above)
    for fid, v in updates.items():
        frow = by_id.get(fid)
        ok, msg = _validate_value(frow, v)
        if not ok:
            _log("error", "VALIDATION_ERROR", msg or "Invalid field value.", {"field_id": fid})
            return _err("VALIDATION_ERROR", msg or "Invalid field value.", field_id=fid, field_name=frow.get("name"))

    # Uniqueness check across active records excluding self
    enforce_nulls_default = False
    for f in active_fields:
        if not f.get("is_unique"):
            continue
        fid = f.get("id")
        if fid not in updates and fid not in merged:
            continue
        val = merged.get(fid)
        opts = f.get("options") if isinstance(f.get("options"), dict) else {}
        enforce_nulls = bool(opts.get("enforce_unique_nulls", enforce_nulls_default))
        if (val is None or val == "" or val == []) and not enforce_nulls:
            continue
        if isinstance(val, (dict, list)):
            _log("error", "VALIDATION_ERROR", "Unique constraint only supported for scalar values.", {"field_id": fid})
            return _err("VALIDATION_ERROR", "Unique constraint only supported for scalar values.", field_id=fid)
        for r in records_rows:
            if r.get("id") == record_id:
                continue
            if r.get("table_id") != table_id or r.get("status") != "active":
                continue
            other = (r.get("fields") or {}).get(fid)
            if other == val and not (other is None and not enforce_nulls):
                _log("error", "CONFLICT", "Uniqueness constraint violated.", {"field_id": fid})
                return _err("CONFLICT", "Uniqueness constraint violated.", field_id=fid, field_name=f.get("name"))

    # Persist update
    now = _now()
    rec_row["fields"] = merged
    rec_row["updated_at"] = now
    _save("records.json", records_rows)

    # Update search index
    idx = _load("record_search_index.json")
    if not isinstance(idx, list):
        idx = []
    schema_version = int(table_row.get("schema_version") or 1)

    search_text_parts = []
    search_kv = {}
    for f in active_fields:
        fid = f.get("id")
        val = merged.get(fid)
        if f.get("is_indexed"):
            if f.get("type") in ("singleLineText", "multilineText", "email", "url", "phoneNumber"):
                if val is not None:
                    search_text_parts.append(_normalize_text(val))
            else:
                if val is not None:
                    search_kv[fid] = val
    search_text = " ".join([p for p in search_text_parts if p]).strip()

    existing = None
    for r in idx:
        if r.get("table_id") == table_id and r.get("record_id") == record_id:
            existing = r
            break
    if existing:
        existing["schema_version"] = schema_version
        existing["status"] = "fresh"
        existing["search_text"] = search_text
        existing["search_kv"] = search_kv
        existing["updated_at"] = now
    else:
        # create missing index row
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def _new_id(prefix, n=19):
            return prefix + "_" + "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(n))
        idx.append({
            "id": _new_id("rsi"),
            "table_id": table_id,
            "record_id": record_id,
            "schema_version": schema_version,
            "status": "fresh",
            "search_text": search_text,
            "search_kv": search_kv,
            "created_at": now,
            "updated_at": now,
        })
    _save("record_search_index.json", idx)

    _log("ok")
    return {"record": rec_row}

def delete_record(table_id, record_id, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_record"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_s, code=None, message=None, meta=None):
        fn = _get_log_store()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        rows.append(row)
        _save(fn, rows)

    if not isinstance(table_id, str) or not table_id.startswith("tbl_"):
        out = _err("VALIDATION_ERROR", "Invalid table_id.", field="table_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if not isinstance(record_id, str) or not record_id.startswith("rec_"):
        out = _err("VALIDATION_ERROR", "Invalid record_id.", field="record_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []
    table = next((t for t in tables if t.get("id") == table_id), None)
    if not table or table.get("status") == "deleted":
        out = _err("NOT_FOUND", "Table not found.", table_id=table_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if table.get("status") != "active":
        out = _err("UNAUTHORIZED", "Table is not active; record mutations are not allowed.", table_status=table.get("status"))
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    r_idx = next((i for i, r in enumerate(records) if r.get("id") == record_id), None)
    if r_idx is None:
        out = _err("NOT_FOUND", "Record not found.", record_id=record_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    rec = records[r_idx]
    if rec.get("table_id") != table_id:
        out = _err("NOT_FOUND", "Record not found in the specified table.", table_id=table_id, record_id=record_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    # Idempotent delete
    now = _now()
    if rec.get("status") == "deleted":
        out = {"record": rec, "deleted": True, "idempotent": True}
        _log("ok")
        return out

    # Transition active -> deleted
    rec["status"] = "deleted"
    rec["deleted_at"] = now
    rec["updated_at"] = now
    records[r_idx] = rec
    _save("records.json", records)

    # Cascade to search index: status must be deleted
    idx_rows = _load("record_search_index.json")
    if not isinstance(idx_rows, list):
        idx_rows = []
    ix = next((x for x in idx_rows if x.get("table_id") == table_id and x.get("record_id") == record_id), None)
    if ix:
        ix["status"] = "deleted"
        ix["updated_at"] = now
    _save("record_search_index.json", idx_rows)

    out = {"record": rec, "deleted": True}
    _log("ok")
    return out

def search_records(table_id, query=None, filter=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, secrets, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_records"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_log_store():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_s, code=None, message=None, meta=None):
        fn = _get_log_store()
        if not fn:
            return
        rows = _load(fn)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        rows.append(row)
        _save(fn, rows)

    def _encode_cursor(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return "bad"
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        raw = None
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return "bad"

    if not isinstance(table_id, str) or not table_id.startswith("tbl_"):
        out = _err("VALIDATION_ERROR", "Invalid table_id.", field="table_id")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if query is not None and not isinstance(query, str):
        out = _err("VALIDATION_ERROR", "query must be a string.", field="query")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if filter is not None and not isinstance(filter, dict):
        out = _err("VALIDATION_ERROR", "filter must be an object.", field="filter")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if status is not None and status not in ("active", "deleted", "all"):
        out = _err("VALIDATION_ERROR", "status must be one of active/deleted/all.", field="status")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    if sort is not None:
        if not isinstance(sort, list):
            out = _err("VALIDATION_ERROR", "sort must be an array.", field="sort")
            _log("error", out["error"]["code"], out["error"]["message"])
            return out
        for s in sort:
            if not isinstance(s, dict) or "field" not in s or "direction" not in s or s.get("direction") not in ("asc", "desc") or not isinstance(s.get("field"), str):
                out = _err("VALIDATION_ERROR", "Each sort item must have field (string) and direction (asc|desc).", field="sort")
                _log("error", out["error"]["code"], out["error"]["message"])
                return out

    cur = _decode_cursor(cursor)
    if cur == "bad":
        out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        _log("error", out["error"]["code"], out["error"]["message"])
        return out
    offset = 0
    if isinstance(cur, dict):
        if cur.get("table_id") != table_id:
            out = _err("VALIDATION_ERROR", "cursor does not match table_id.", field="cursor")
            _log("error", out["error"]["code"], out["error"]["message"])
            return out
        try:
            offset = int(cur.get("offset", 0))
        except Exception:
            offset = 0
        if offset < 0:
            offset = 0

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []
    table = next((t for t in tables if t.get("id") == table_id), None)
    if not table or table.get("status") == "deleted":
        out = _err("NOT_FOUND", "Table not found.", table_id=table_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    # Prefer search index if fresh for this schema_version; else fall back to scan indexed fields
    idx_rows = _load("record_search_index.json")
    if not isinstance(idx_rows, list):
        idx_rows = []
    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    all_fields = _load("fields.json")
    if not isinstance(all_fields, list):
        all_fields = []
    active_fields = [f for f in all_fields if f.get("table_id") == table_id and f.get("status") == "active"]
    field_by_id = {f.get("id"): f for f in active_fields if isinstance(f.get("id"), str)}
    field_by_name = {f.get("name"): f for f in active_fields if isinstance(f.get("name"), str)}
    indexed_field_ids = set([f.get("id") for f in active_fields if f.get("is_indexed") and isinstance(f.get("id"), str)])

    schema_version = int(table.get("schema_version") or 1)
    use_index = True
    for ix in idx_rows:
        if ix.get("table_id") == table_id and ix.get("status") == "fresh" and int(ix.get("schema_version") or 0) != schema_version:
            use_index = False
            break
        if ix.get("table_id") == table_id and ix.get("status") == "stale":
            use_index = False
            break

    wanted_status = status or "active"

    def _record_status_ok(r):
        rs = r.get("status")
        if wanted_status == "all":
            return rs in ("active", "deleted")
        return rs == wanted_status

    def _matches_filter_kv(kv, fil):
        if not fil:
            return True
        for fk, fv in fil.items():
            # allow field name or id
            fid = fk
            if fk in field_by_name:
                fid = field_by_name[fk]["id"]
            if fid not in indexed_field_ids:
                return False
            if kv.get(fid) != fv:
                return False
        return True

    qnorm = None
    if isinstance(query, str) and query.strip() != "":
        qnorm = " ".join(query.lower().split())

    matched_ids = []
    if use_index:
        # Join index -> record
        idx_for_table = [ix for ix in idx_rows if ix.get("table_id") == table_id and ix.get("status") != "deleted"]
        # Apply filters
        for ix in idx_for_table:
            rid = ix.get("record_id")
            r = next((rr for rr in records if rr.get("id") == rid), None)
            if not r or r.get("table_id") != table_id:
                continue
            if not _record_status_ok(r):
                continue
            if qnorm and qnorm not in (ix.get("search_text") or "").lower():
                continue
            if not _matches_filter_kv(ix.get("search_kv") or {}, filter or {}):
                continue
            matched_ids.append(rid)
    else:
        # Fallback scan: only indexed fields participate
        for r in records:
            if r.get("table_id") != table_id:
                continue
            if not _record_status_ok(r):
                continue
            rf = r.get("fields") or {}
            if not isinstance(rf, dict):
                continue
            # filter
            ok = True
            if isinstance(filter, dict) and filter:
                for fk, fv in filter.items():
                    fid = fk
                    if fk in field_by_name:
                        fid = field_by_name[fk]["id"]
                    if fid not in indexed_field_ids:
                        ok = False
                        break
                    if rf.get(fid) != fv:
                        ok = False
                        break
            if not ok:
                continue
            if qnorm:
                text = []
                for fid in indexed_field_ids:
                    v = rf.get(fid)
                    if v is None:
                        continue
                    if isinstance(v, str):
                        text.append(v.lower())
                    elif isinstance(v, list):
                        text.extend([str(x).lower() for x in v])
                    else:
                        text.append(str(v).lower())
                if qnorm not in " ".join(text):
                    continue
            matched_ids.append(r.get("id"))

    # Build record list
    matched_records = [next((r for r in records if r.get("id") == rid), None) for rid in matched_ids]
    matched_records = [r for r in matched_records if r is not None]

    # Sorting
    if sort:
        def _sort_key_builder(spec):
            fld = spec.get("field")
            direction = spec.get("direction")
            fid = fld
            if fld in field_by_name:
                fid = field_by_name[fld]["id"]
            def _key(rec):
                v = (rec.get("fields") or {}).get(fid)
                # normalize types for comparison
                if v is None:
                    return (1, "")
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    return (0, v)
                return (0, str(v))
            reverse = (direction == "desc")
            return _key, reverse
        # Apply stable sorts from last to first
        for spec in reversed(sort):
            key_fn, rev = _sort_key_builder(spec)
            matched_records.sort(key=key_fn, reverse=rev)
    else:
        # deterministic order by created_at then id
        matched_records.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    total = len(matched_records)
    page = matched_records[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"table_id": table_id, "offset": next_offset}) if has_more else None

    out = {"records": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok")
    return out

def get_record(table_id, record_id, include_deleted=None, **_extra):
