    table = next((t for t in tables if t.get("id") == table_id), None)
    if not table or table.get("status") == "deleted":
        out = _err("NOT_FOUND", "Table not found.", table_id=table_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    rec = next((r for r in records if r.get("id") == record_id), None)
    if not rec or rec.get("table_id") != table_id:
        out = _err("NOT_FOUND", "Record not found.", table_id=table_id, record_id=record_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    if rec.get("status") == "deleted" and not include_deleted:
        out = _err("NOT_FOUND", "Record not found.", table_id=table_id, record_id=record_id)
        _log("error", out["error"]["code"], out["error"]["message"])
        return out

    out = {"record": rec}
    _log("ok")
    return out

