def create_base(name, owner_user_id=None, metadata=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_base"
    status_code = "ok"
    used_cred = None

    def _log_and_return(payload):
        nonlocal status_code
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": used_cred,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": datetime.datetime.utcnow().isoformat() + "Z"
        })
        _save("request_logs.json", logs)
        return payload

    if not isinstance(name, str):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "name must be a string.", field="name"))
    nm = name.strip()
    if len(nm) < 1 or len(nm) > 255:
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "name length must be between 1 and 255.", field="name"))
    if owner_user_id is not None and not isinstance(owner_user_id, str):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "owner_user_id must be a string.", field="owner_user_id"))
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "metadata must be a JSON object.", field="metadata"))

    bases = _load("bases.json")
    if not isinstance(bases, list):
        bases = []

    # Uniqueness: unique(name, owner_user_id) where status != 'deleted'
    for b in bases:
        if not isinstance(b, dict):
            continue
        if b.get("status") != "deleted" and b.get("name") == nm and b.get("owner_user_id") == owner_user_id:
            status_code = "error"
            return _log_and_return(_err("CONFLICT", "A base with this name already exists for the owner.", field="name"))

    now = datetime.datetime.utcnow().isoformat() + "Z"
    rid = "bas_" + secrets.token_hex(12).upper()  # 24 hex => 24 chars, meets {18,}
    new_base = {
        "id": rid,
        "name": nm,
        "status": "active",
        "owner_user_id": owner_user_id,
        "metadata": metadata,
        "created_at": now,
        "updated_at": now
    }
    bases.append(new_base)
    _save("bases.json", bases)

    status_code = "ok"
    return _log_and_return({"base": new_base})

