def list_fields(table_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0024000" if __import__("os").path.isdir("./environment_mix/0024000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_fields"
    status_code = "ok"
    used_cred = None

    def _log_and_return(payload):
        nonlocal status_code
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": used_cred,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": datetime.datetime.utcnow().isoformat() + "Z"
        })
        _save("request_logs.json", logs)
        return payload

    if not isinstance(table_id, str) or not re.match(r"^tbl_[0-9A-Z]{18,}$", table_id):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Malformed table_id.", field="table_id"))

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "hidden", "deleted"):
            status_code = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status filter.", field="status"))

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit"))

    if sort is None:
        sort = "position"
    if not isinstance(sort, str) or sort not in ("position", "created_at", "updated_at", "name"):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid sort.", field="sort"))

    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        status_code = "error"
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid order.", field="order"))

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            status_code = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Malformed cursor.", field="cursor"))
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("off:"):
                status_code = "error"
                return _log_and_return(_err("VALIDATION_ERROR", "Malformed cursor.", field="cursor"))
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            status_code = "error"
            return _log_and_return(_err("VALIDATION_ERROR", "Malformed cursor.", field="cursor"))

    tables = _load("tables.json")
    if not isinstance(tables, list):
        tables = []
    table = next((t for t in tables if isinstance(t, dict) and t.get("id") == table_id), None)
    if not table:
        status_code = "error"
        return _log_and_return(_err("NOT_FOUND", "Table not found."))

    fields = _load("fields.json")
    if not isinstance(fields, list):
        fields = []

    rows = [f for f in fields if isinstance(f, dict) and f.get("table_id") == table_id]
    if status is not None:
        rows = [f for f in rows if f.get("status") == status]

    def _key(v):
        if sort in ("created_at", "updated_at"):
            return v.get(sort) or ""
        if sort == "position":
            pv = v.get("position")
            return pv if isinstance(pv, int) else 10**18
        return (v.get("name") or "").lower()

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8")

    status_code = "ok"
    return _log_and_return({
        "fields": page,
        "meta": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": limit,
            "sort": sort,
            "order": order
        }
    })
